  str_n27_5_name = "N4 - Entrega de cartas",
  str_n27_6_name = "N5 - Antídoto",
  str_n27_7_name = "N6 - Separación",
  str_n27_8_name = "N7 - Eclipses",
  str_n27_9_name = "ST2 - Desierto",
  str_n27_10_name = "N8 - Desvío",
  str_n27_11_name = "N9 - Otra batalla",
  str_n27_12_name = "N10 - Separado",
  str_n27_13_name = "N11 - Oasis",
  str_n27_14_name = "N12 - El deseo del corazón",
  str_n27_15_name = "ST3 - Nupcias",
  str_n27_1_name_desc = "—",
  str_n27_2_name_desc = "Una boda caótica te causa un dilema, y la novia Tara aparentemente sufre de amnesia.",
  str_n27_3_name_desc = "Después de llegar a Lumopolis, Naroxel le da a la pareja una tarea especial antes de otorgarles su sello de aprobación: ayudar a Courier Union a vender sellos de edición limitada para el Día de la Corona de Luna.",
  str_n27_4_name_desc = "Vas a Umbraton con Adonis para descansar y relajarte, pero sin darte cuenta descubres que Black Umbrella Laboratories en Illumina podría examinar a Tara y su condición.",
  str_n27_5_name_desc = "Después de llegar a Illumina, te encuentras con Dove en Gannon City. Ella promete que mientras la ayudes a entregar sus envíos atrasados, otorgará un sello a la pareja.",
  str_n27_6_name_desc = "En Black Umbrella Laboratories, Jola te dice que podría intentar hacer un antídoto si tuviera las escamas del raro gusano de arena. Pero Adonis cree que no tiene ninguna posibilidad contra una criatura así.",
  str_n27_7_name_desc = "Jeriah llama a Sable y Adonis para un entrenamiento de batalla, pero ninguno se atreve a atacar.",
  str_n27_8_name_desc = "La identidad de Sable está casi expuesta en Gannon City. Kya le promete que la llevará a casa.",
  str_n27_9_name_desc = "—",
  str_n27_10_name_desc = "Temprano al día siguiente, empaca sus cosas y se prepara para partir en busca del raro gusano de arena rosa.",
  str_n27_11_name_desc = "Justo después de que termines de comer, aparece otro grupo de Eclipsites. La aparición de tantos eclipses pone nervioso a Jeriah.",
  str_n27_12_name_desc = "El gusano de arena rosa es extremadamente astuto. Utiliza las ventajas de su terreno nativo para separar a todos y ponerlos a todos en peligro...",
  str_n27_13_name_desc = "Partiste hacia el oasis rosa infestado de gusanos de arena en el vehículo de Jeriah, con la esperanza de que Kya y los demás no sufrieran ningún daño...",
  str_n27_14_name_desc = "Adonis y Kya están bien, pero ¿dónde está Sable?",
  str_n27_15_name_desc = "—",
  str_n27_level_desc_long_1 = "A medida que se acerca el Día de la Corona de la Luna, Naroxel te confía un recado especial: escoltar a la prometida de su amiga desde el desierto de Rediesel hasta Northland. La acompaña un miembro senior de la división Rediesel Wrench de Courier Union llamado Jeriah. Te pones en marcha de inmediato, pero las cosas no van tan bien.",
  str_n27_level_desc_long_2 = "Inspirada por las palabras de Jeriah, Tara decide poner a prueba la sinceridad de Adonis fingiendo amnesia. Después de no poder encontrar el antídoto, una poción psicológica de uso múltiple, Adonis escucha la sugerencia de Jeriah y lleva a Tara a participar en las festividades del Día de la Luna de la Corona de la Unión de Mensajeros en todo el continente.",
  str_n27_level_desc_long_3 = "Después de llegar a Lumopolis, Naroxel le pide a la pareja que complete la prueba del sello de una manera relativamente dulce y conmovedora: vendiendo sellos del Día de la Luna Coronada, y espera que usted y Jeriah continúen ayudándolos. Pero incluso si se completa la prueba de sellado, puede que no sea suficiente para cerrar la brecha entre ellos.",
  str_n27_level_desc_long_4 = "Llevas a Adonis a relajarse en Umbraton, pero te enredas en una travesura con Hachi y Gin. Después de deshacerte de ellos, Dina te dice que podrías ir a Black Umbrella Laboratories para verificar la condición de Tara por ti mismo.",
  str_n27_level_desc_long_5 = "Encuentras a Dove escondida en la oficina del sindicato, holgazaneando en el trabajo. Ella dice casualmente que sellará el sello siempre que la ayudes con su acumulación de pedidos. Tú y tu grupo comienzan a ayudar a Dove a entregar cartas, mientras que Kya lleva a Sable a buscar pistas sobre su memoria en Gannon City.",
  str_n27_level_desc_long_6 = "Te diriges a Black Umbrella Laboratories, donde Jola te dice que podría hacer un antídoto si tuviera las escamas de un raro gusano de arena. Adonis se desespera ante la idea, pero no está listo para darse por vencido. Jeriah cree que el lugar perfecto para comenzar sería perfeccionando su coraje.",
  str_n27_level_desc_long_7 = "Adonis y Sable comienzan a pelear pero llegan a un callejón sin salida. Adonis se irrita por la provocación de Jeriah, lo que le hace reunir el coraje para atacar. Este ataque parece evocar recuerdos del desierto en la mente de Sable. Sin embargo, Jeriah ya ha percibido la verdadera identidad de Sable y se enfrenta a Kya.",
  str_n27_level_desc_long_8 = "Kya lleva a Sable a comprar comida, pero Sable se desmaya debido a sus recuerdos crecientes, casi exponiendo su identidad. Kya se la lleva para escapar de la multitud. Cuando Sable despierta, recuerda que una vez fue una auroriana, engañada por su amado, y su hogar parece haber estado en algún lugar del desierto de Rediesel.",
  str_n27_level_desc_long_9 = "Regresa a la sucursal Rediesel Wrench de Courier Union, planea recuperarse aquí durante la noche y comenzar de nuevo. Jeriah va a verificar el estado de los vehículos y empacar el equipo mientras Tara arrastra a Adonis para encender una fogata y preparar una comida al estilo Rediesel Wrench.",
  str_n27_level_desc_long_10 = "A la mañana siguiente, empaca su equipo y se prepara para partir. Sin embargo, Adonis dice que no durmió mucho gracias a la cecina de lagarto picante que comió la noche anterior. Todo lo que puede hacer ahora es tratar de mantener el ánimo y seguirlo, pero ¿realmente está bien?",
  str_n27_level_desc_long_11 = "Después de derrotar a dos grupos de Eclipsites en sucesión, el astuto Jeriah nota algo inusual: estos Eclipsites no están peleando en absoluto. De hecho, ¡es más como si estuvieran corriendo por sus vidas! En ese momento, finalmente se muestra la razón por la cual los Eclipsites están corriendo con tal frenesí. ¡Es el raro gusano de arena rosa!",
  str_n27_level_desc_long_12 = "Estás atrapado en una ardua batalla con el gusano de arena rosa. Finalmente, el gusano de arena usa su astucia para escapar, levantando una nube de polvo y llevándose a Adonis, Kya y Sable. Jeriah envía a su Portavoz a buscar a tus compañeros perdidos, pero no puede encontrarlos. Ante esta crisis, finalmente decide bajar la guardia y pedir ayuda a la gente del desierto.",
  str_n27_level_desc_long_13 = "Jeriah te lleva al oasis donde habita el gusano de arena rosa. Aquí, encuentras a Adonis y Kya inconscientes, pero Sable, llevado por el gusano de arena, no se encuentra por ningún lado. Cuando Adonis se despierta, Tara le cuenta la verdad sobre su fingida amnesia...",
  str_n27_level_desc_long_14 = "Para encontrar a Sable, Jeriah envía a su Portavoz nuevamente. Esta vez, el Portavoz trae rastros de Sable. Resulta que Sable luchó contra el gusano de arena rosa para proteger a los dos aurorianos inconscientes, y su verdadera identidad no es la de un pariente de Kya...",
  str_n27_level_desc_long_15 = "Después de muchos giros inesperados, Tara y Adonis finalmente llegan a conocerse mejor, con la ayuda de Jeriah. Pasan con éxito la prueba y obtienen la aprobación de sus familias. Al final, se convierten en una pareja feliz. Completas la encomienda de Naroxel y recibes su recompensa; ahora es el momento de regresar a Soroz.",
  str_n27_h1_name = "H1 - Velocidad de ampollas",
  str_n27_h2_name = "H2 - Formación",
  str_n27_h3_name = "H3 - Intersección",
  str_n27_h4_name = "H4 - Cortado",
  str_n27_h1_name_desc = "¡Más rápido! ¡Más rápido! ¡La velocidad lo es todo! ¡No solo debemos correr por el camino hacia el futuro a toda velocidad, sino que también debemos luchar contra los enemigos que se abren camino de frente!",
  str_n27_h2_name_desc = "Parece que tendremos la ayuda de fuerzas amigas en esta batalla, y parecen haber tomado algún tipo de formación militar. ¿Tal vez podamos usar esto?",
  str_n27_h3_name_desc = "Donde los tres lados se cruzan surge una forma de enfrentarse al enemigo desde tres flancos diferentes, pero en los márgenes... también se presenta un \"atajo\" potencial.",
  str_n27_h4_name_desc = "El terreno está roto y el abismo rodea... Aunque muchos enemigos no se ven afectados por tales condiciones, afortunadamente, tienes un aliado que puede superar tales complicaciones...",
  str_n27_bh1_name = "EX1 - En llamas",
  str_n27_bh2_name = "EX2 - Temblores",
  str_n27_bh3_name = "EX3 - Vejación",
  str_n27_bh1_sub_name_1 = "EX1-1 Reanimar",
  str_n27_bh1_sub_name_2 = "EX1-2 Desesperación",
  str_n27_bh2_sub_name_1 = "EX2-1 Destello espinoso",
  str_n27_bh2_sub_name_2 = "EX2-2 depredador",
  str_n27_bh3_sub_name_1 = "EX3-1 Calavera Tóxica",
  str_n27_bh3_sub_name_2 = "EX3-2 Barredora de arena",
  str_n27_bh3_sub_name_3 = "EX3-3 Ciempiés"
